import {calendarModes,monthlyStates} from './monthly-contract.mjs';
export function createMonthlyView({api,h,heading,showPanel,localTime,writable,onCalendarEdit}){
 const $=s=>document.querySelector(s);let month='',memberId='',identity,request,viewController,serial=0;
 const duration=n=>`${Math.floor(n/60)} 小时 ${n%60} 分钟`,fmt=v=>v?localTime(v):'未登记';
 return {async render(parentSignal,user,back){
  viewController?.abort();viewController=new AbortController();const signal=AbortSignal.any([parentSignal,viewController.signal]);
  if(identity!==user.id){identity=user.id;memberId='';month=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date());}
  $('#main').innerHTML=heading('月度考勤','工作日历、原始记录与审核结果汇总。当前为动态预览，尚未锁定考勤月份。')+`<section class="work-panel module-panel"><div class="module-toolbar"><button class="secondary" id="monthly-back">返回考勤审核</button><label>月份<input id="monthly-month" type="month" min="1900-01" max="2199-12" value="${h(month)}"></label><label ${user.role==='admin'?'':'hidden'}>成员<select id="monthly-member"></select></label></div><p class="muted">默认周一至周五工作；管理员可逐日登记节假日和调休。未来日期不计缺勤，今日未开始不计缺勤。请假时长按批准区间与本月相交的自然时间展示，不折算应出勤或工资。</p><div id="monthly-result">正在读取月度考勤…</div></section>`;
  const load=async()=>{
   request?.abort();request=new AbortController();const combined=AbortSignal.any([signal,request.signal]),current=++serial;$('#monthly-result').textContent='正在读取月度考勤…';
   try{const v=await api.monthlyAttendance(month,user.role==='admin'?memberId:undefined,combined);if(combined.aborted||serial!==current)return;$('#monthly-member').innerHTML=v.roster.map(m=>`<option value="${h(m.id)}">${h(m.name)}${!m.active||!m.loginActive?'（已停用）':''}</option>`).join('');if(!v.member){$('#monthly-result').innerHTML='<p class="empty">暂无可汇总的员工档案。</p>';return;}memberId=v.member.id;$('#monthly-member').value=memberId;const s=v.summary;
    const stats=[['整月计划工作日',s.expectedDays],['截至今日工作日',s.elapsedExpectedDays],['正常工作日',s.normalDays],['迟到',s.lateDays],['时长不足',s.insufficientDays],['批准请假涉及天数',s.leaveDays],['批准请假区间时长',duration(s.leaveMinutes)],['无记录待核实',s.unverifiedAbsenceDays],['批准补卡',s.approvedCorrections],['待审核补卡',s.pendingCorrections],['休息日有工作记录',s.restWorkDays],['记录待核对',s.needsReviewDays],['时间异常待核实',s.pendingExceptions]];
    $('#monthly-result').innerHTML=`<h3>${h(v.member.name)} · ${h(v.month)}</h3>${!v.member.startDate?'<p class="planning-rule">未登记入职日期，计划工作日暂按整月展示；请补全人员资料后再核定。</p>':`<p class="muted">入职日期：${h(v.member.startDate)}；入职前日期不计应出勤。</p>`}${!v.member.active||!v.member.loginActive?'<p class="planning-rule">该成员或账号已停用；未登记离职生效日，本汇总不能据此推断离职后的应出勤。</p>':''}<dl class="record-facts">${stats.map(([k,n])=>`<div><dt>${h(k)}</dt><dd>${h(n)}</dd></div>`).join('')}</dl><p class="muted">迟到与时长不足可能在同一天同时发生。核实说明保留时间事实；所有计数均用于核对，不直接生成奖罚。</p><div class="monthly-days">${v.days.map(d=>`<button class="asset-row" data-monthly-day="${h(d.date)}"><span><b>${h(d.date)}</b><small>${d.workday?'工作日':'休息日'}${d.calendar.mode!=='default'?' · 已调整':''}</small></span><span><b>${h(monthlyStates[d.state])}${d.complete&&d.metrics.late?' · 迟到':''}${d.complete&&d.metrics.insufficient?' · 时长不足':''}</b><small>上班 ${h(fmt(d.inAt))} / 下班 ${h(fmt(d.outAt))}${d.leaves.length?' · 有请假':''}${d.corrections.length?' · 有补卡申请':''}</small></span><span class="task-arrow">›</span></button>`).join('')}</div>`;
    document.querySelectorAll('[data-monthly-day]').forEach(b=>b.onclick=()=>detail(v.days.find(d=>d.date===b.dataset.monthlyDay)));
   }catch(e){if(!combined.aborted&&$('#monthly-result'))$('#monthly-result').textContent=e.message;}
  };
  const detail=async d=>{let history,panelSignal;await showPanel('逐日考勤明细',async ps=>{panelSignal=ps;history=await api.calendarHistory(d.date,0,AbortSignal.any([signal,ps]));return `<div class="dialog-header"><h2>${h(d.date)}</h2><button class="icon-button" id="monthly-close" aria-label="关闭明细">×</button></div><p>${d.workday?'工作日':'休息日'} · ${h(calendarModes[d.calendar.mode])}</p><p class="preserve-text">${h(d.calendar.note||'按默认周历，无额外安排。')}</p>${writable&&user.role==='admin'?`<button class="secondary" id="monthly-calendar-edit">调整当日安排</button>`:''}<h3>考勤记录</h3>${d.periods.map(p=>`<button class="asset-row" data-attendance-detail="${h(p.id)}"><span><b>${p.kind==='studio'?'工作室记录':'历史外勤'}</b><small>原始：${h(fmt(p.original_in))} → ${h(fmt(p.original_out))}</small><small>核准：${h(fmt(p.adjusted_in||p.original_in))} → ${h(fmt(p.adjusted_out||p.original_out))}</small></span><span>查看与补正 ›</span></button>`).join('')||'<p class="muted">没有打卡记录。</p>'}<h3>请假与补卡</h3>${d.leaves.map(l=>`<button class="asset-row" data-leave-detail="${h(l.id)}"><span>${h(l.type)} · ${l.status==='approved'?'已批准':'待审核'} · 当日相交 ${h(duration(l.minutes))}</span><span>›</span></button>`).join('')}${d.corrections.map(c=>`<button class="asset-row" data-attendance-detail="${h(c.id)}" data-correction="true"><span>补卡 · ${h({pending:'待审核',approved:'已批准',rejected:'已驳回'}[c.status])}</span><span>›</span></button>`).join('')||(!d.leaves.length?'<p class="muted">无请假或补卡申请。</p>':'')}<h3>当日日历修改历史</h3><div id="monthly-calendar-history"></div><button class="secondary" id="monthly-history-more" ${history.total<=50?'hidden':''}>继续查看历史</button>`;});
   if(signal.aborted||!history||panelSignal.aborted)return;$('#monthly-close')?.addEventListener('click',()=>$('#cloud-detail').close());$('#monthly-calendar-edit')?.addEventListener('click',()=>onCalendarEdit(d.date));let offset=0,busy=false;const historyLoad=async(first)=>{if(busy)return;busy=true;try{const result=first||await api.calendarHistory(d.date,offset,AbortSignal.any([signal,panelSignal]));if(signal.aborted||panelSignal.aborted||!$('#monthly-calendar-history'))return;$('#monthly-calendar-history').insertAdjacentHTML('beforeend',result.rows.map(r=>`<article class="observation"><b>${h(r.actor_name)} · ${h(fmt(r.created_at))}</b><p>${h(calendarModes[r.after_value.mode])}</p><p class="preserve-text">${h(r.after_value.note)}</p></article>`).join('')||(offset===0?'<p class="muted">没有调整记录。</p>':''));offset+=result.rows.length;$('#monthly-history-more').hidden=offset>=result.total;}finally{busy=false;}};$('#monthly-history-more').onclick=()=>historyLoad().catch(e=>{if(!signal.aborted&&!panelSignal.aborted&&$('#monthly-calendar-history'))$('#monthly-calendar-history').textContent=e.message;});await historyLoad(history);
  };
  $('#monthly-back').onclick=()=>{viewController.abort();back();};$('#monthly-month').onchange=()=>{month=$('#monthly-month').value;load();};$('#monthly-member').onchange=()=>{memberId=$('#monthly-member').value;load();};signal.addEventListener('abort',()=>request?.abort(),{once:true});await load();
 }};
}
